    {section==='Contracts'?<><Text style={s.section}>{copy.contractsTitle}</Text><Text style={s.muted}>{earning?t("Three contracts rotate daily at 00:00 UTC. Accept up to two; only activity completed after acceptance counts."):t("Only completed contracts accepted on the final event day can now be claimed.")}</Text>{contracts.map(contract=>{const {objective}=contract,ready=contract.progress>=objective.required,pct=Math.min(100,contract.progress/objective.required*100);return <View key={contract.id} style={[s.card,ready&&s.ready]}><View style={s.between}><View style={s.flex}><Text style={s.rewardName}>{objective.name}</Text><Text style={s.muted}>{objective.description}</Text></View><Text style={s.contractCount}>{Math.min(contract.progress,objective.required)}/{objective.required}</Text></View><View style={s.track}><View style={[s.fill,{width:`${pct}%`,backgroundColor:ready?C.good:definition.accent}]}/></View><Text style={s.rewardLine}>+{objective.rewardCurrency} {definition.currencyName} · +{objective.rewardPrestige} {definition.prestigeCurrencyName}</Text>{!contract.accepted?<GameButton compact title={earning?t("Accept contract"):t("Not accepted")} disabled={!earning} tone="secondary" onPress={()=>act(t("{name} accepted. Progress starts now.",{name:objective.name}),()=>acceptEventContract(state,objective.id,now),{type:'event_accept',args:{id:objective.id}})}/>:<GameButton compact title={contract.claimed?t("Claimed"):ready?t("Claim contract"):earning?t("In progress"):t("Incomplete")} disabled={contract.claimed||!ready} onPress={()=>act(t("Contract rewards claimed."),()=>claimEventObjective(state,objective.id,now),{type:'event_objective',args:{id:objective.id}})}/>}</View>})}<Text style={s.section}>{t("WEEKLY FESTIVAL CHALLENGES")}</Text><Text style={s.muted}>{earning?t("Weekly activity is counted automatically from Monday 00:00 UTC. No acceptance slot is required."):t("The final event week is frozen. Completed rewards remain claimable.")}</Text>{weeklies.map(challenge=>{const {objective}=challenge,ready=challenge.progress>=objective.required,pct=Math.min(100,challenge.progress/objective.required*100);return <View key={challenge.id} style={[s.card,ready&&s.ready]}><View style={s.between}><View style={s.flex}><Text style={s.rewardName}>{objective.name}</Text><Text style={s.muted}>{objective.description}</Text></View><Text style={s.contractCount}>{Math.min(challenge.progress,objective.required)}/{objective.required}</Text></View><View style={s.track}><View style={[s.fill,{width:`${pct}%`,backgroundColor:ready?C.good:definition.accent}]}/></View><Text style={s.rewardLine}>+{objective.rewardCurrency} {definition.currencyName} · +{objective.rewardPrestige} {definition.prestigeCurrencyName}</Text><GameButton compact title={challenge.claimed?t("Claimed"):ready?t("Claim weekly reward"):earning?t("In progress"):t("Incomplete")} disabled={challenge.claimed||!ready} onPress={()=>act(t("Weekly event reward claimed."),()=>claimEventWeeklyObjective(state,objective.id,now),{type:'event_weekly',args:{id:objective.id}})}/></View>})}</>:null}

    {section==='Shop'?<><Text style={s.section}>{copy.shopTitle}</Text><Text style={s.muted}>{t("Two common-currency offers rotate daily. Prestige stock remains available for the full event. Purchased cosmetics stay account-bound.")}</Text>{shopOffers.map(offer=>{const count=eventOfferPurchaseCount(state,id,offer.id),sold=count>=offer.limit,balance=offer.currency==='common'?marks:seeds,color=rarityColor[offer.reward.rarity];return <View key={offer.id} style={[s.reward,stackEvent&&s.rewardStack,{borderColor:color}]}>{<RewardArtwork reward={offer.reward} rewardArt={visuals.rewardArt} color={color} size={88} onPress={()=>setPreviewReward({reward:offer.reward,color})}/>} <View style={s.rewardCopy}><Text style={[s.rewardType,{color}]}>{offer.legacy?'LEGACY · ':''}{p(offer.reward.rarity.charAt(0).toUpperCase()+offer.reward.rarity.slice(1)).toUpperCase()} · {p(offer.reward.kind.charAt(0).toUpperCase()+offer.reward.kind.slice(1).replaceAll('_',' ')).toUpperCase()}</Text><Text style={s.rewardName}>{offer.reward.name}</Text><Text style={s.muted}>{offer.cost.toLocaleString()} {offer.currency==='common'?definition.currencyName:definition.prestigeCurrencyName}</Text></View><View style={[s.claim,stackEvent&&s.claimStack]}><GameButton compact title={sold?t("Owned"):balance>=offer.cost?t("Buy"):t("Locked")} disabled={sold||balance<offer.cost} onPress={()=>act(t("{name} added to your collection.",{name:offer.reward.name}),()=>purchaseEventOffer(state,offer.id,now),{type:'event_purchase',args:{id:offer.id}})}/></View></View>})}</>:null}

